const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define global geometry
  const globalGeom = ee.Geometry.Polygon(
    [[[-180, -60], [180, -60], [180, 75], [-180, 75], [-180, -60]]],
    null, false
  );

  // 2. Load MODIS Land Cover data
  const landCover = ee.ImageCollection('MODIS/006/MCD12Q1')
    .select('LC_Type1'); // IGBP classification

  // Get 2003 and 2019 images
  const lc2003 = landCover.filter(ee.Filter.calendarRange(2003, 2003, 'year')).first();
  const lc2019 = landCover.filter(ee.Filter.calendarRange(2019, 2019, 'year')).first();

  // 3. Check if images exist
  const col2003 = landCover.filter(ee.Filter.calendarRange(2003, 2003, 'year'));
  const col2019 = landCover.filter(ee.Filter.calendarRange(2019, 2019, 'year'));

  const size2003 = col2003.size().getInfo();
  const size2019 = col2019.size().getInfo();

  console.log(`2003 Images: ${size2003}`);
  console.log(`2019 Images: ${size2019}`);

  if (size2003 === 0 || size2019 === 0) {
    console.log("Missing data for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Create crop masks (class 12: croplands, class 14: cropland/natural vegetation mosaic)
  const crops2003 = lc2003.eq(12).or(lc2003.eq(14));
  const crops2019 = lc2019.eq(12).or(lc2019.eq(14));

  // 5. Calculate crop area in square kilometers
  const pixelArea = ee.Image.pixelArea().divide(1e6); // Convert to km²

  const cropArea2003Image = crops2003.multiply(pixelArea);
  const cropArea2019Image = crops2019.multiply(pixelArea);

  // 6. Reduce to get total area
  const area2003Result = cropArea2003Image.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: globalGeom,
    scale: 5000,
    maxPixels: 1e9
  });

  const area2019Result = cropArea2019Image.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: globalGeom,
    scale: 5000,
    maxPixels: 1e9
  });

  const area2003 = area2003Result.get('LC_Type1').getInfo();
  const area2019 = area2019Result.get('LC_Type1').getInfo();

  // 7. Validation
  if (area2003 === null || area2019 === null || isNaN(area2003) || isNaN(area2019)) {
    console.log("Calculation failed - invalid area values.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (area2003 === 0 || area2019 === 0) {
    console.log("No valid crop pixels detected.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Calculate percentage change
  const percentChange = ((area2019 - area2003) / area2003) * 100;

  console.log(`2003 Crop Area: ${(area2003 / 1e6).toFixed(2)} million km²`);
  console.log(`2019 Crop Area: ${(area2019 / 1e6).toFixed(2)} million km²`);
  console.log(`Percent Change: ${percentChange.toFixed(2)}%`);

  // 9. Final answer
  if (percentChange >= 5.0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
